import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db'

export const PRODUCTS_TAG = 'products'

// Shared, cached catalog read. Every view that lists products should use this
// so a single `revalidateTag('products', ...)` refreshes all of them.
export async function getProducts() {
  'use cache'
  cacheTag(PRODUCTS_TAG)
  cacheLife('hours')

  return getAllProducts()
}

import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  const products = await getProducts()

  return (
    <main>
      <h1>Product Catalog</h1>

      <form
        action={async () => {
          'use server'
          // Mark catalog data stale and refresh it in the background
          // (stale-while-revalidate). Admins keep working with the current
          // list while every view using the "products" tag catches up.
          revalidateTag('products', 'max')
        }}
      >
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}
